  [body] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [body_enc] VARCHAR(13) COLLATE Latin1_General_100_CI_AS_SC NOT NULL CONSTRAINT [DF_records_template_body_enc] DEFAULT (N'plain_text'),
  [campaign_hash] CHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [encoding] VARCHAR(6) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [segments] INT NULL,
  [udh_ref] INT NOT NULL CONSTRAINT [DF_records_template_udh_ref] DEFAULT (0),
  [udh_total] INT NOT NULL CONSTRAINT [DF_records_template_udh_total] DEFAULT (0),
  [udh_seq] INT NOT NULL CONSTRAINT [DF_records_template_udh_seq] DEFAULT (0),
  [channel] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ap1] NVARCHAR(50) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ap2] NVARCHAR(50) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [apg1] NVARCHAR(50) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [apg2] NVARCHAR(50) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [priority] INT NULL,
  [protocol] VARCHAR(9) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [ingress] VARCHAR(4) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ip_address] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mcc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mnc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [vendor_id] BIGINT NULL,
  [transport] VARCHAR(9) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [route_id] BIGINT NULL,
  [template_id] BIGINT NULL,
  [status] VARCHAR(9) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [reject_reason] NVARCHAR(190) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [status_code] INT NULL,
  [request_info] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [error_code] NVARCHAR(16) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [vendor_msg_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [raw_dlr] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [concat_parts] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [accepted_at] DATETIME2(0) NULL,
  [delivered_network_at] DATETIME2(0) NULL,
  [delivered_handset_at] DATETIME2(0) NULL,
  [rate_cards] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [buy_price] DECIMAL(12,6) NULL,
  [sell_price] DECIMAL(12,6) NULL,
  [currency] CHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [rated_at] DATETIME2(0) NULL,
  [created_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_records_template_created_at] DEFAULT (SYSUTCDATETIME()),
  [updated_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_records_template_updated_at] DEFAULT (SYSUTCDATETIME()),
  [charge_batch] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  [charge] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  CONSTRAINT [PK_records_template] PRIMARY KEY ([id]),
  CONSTRAINT [CK_records_template_direction] CHECK ([direction] IN ('MT', 'MO')),
  CONSTRAINT [CK_records_template_body_enc] CHECK ([body_enc] IN ('plain_text', 'pii_masked', 'all_encrypted')),
  CONSTRAINT [CK_records_template_encoding] CHECK ([encoding] IN ('gsm7', 'ucs2', 'latin1')),
  CONSTRAINT [CK_records_template_protocol] CHECK ([protocol] IN ('smpp', 'http', 'blackhole')),
  CONSTRAINT [CK_records_template_ingress] CHECK ([ingress] IN ('http', 'smpp')),
  CONSTRAINT [CK_records_template_transport] CHECK ([transport] IN ('smpp', 'http', 'soap', 'blackhole')),
  CONSTRAINT [CK_records_template_status] CHECK ([status] IN ('queued', 'sent', 'delivered', 'failed', 'expired', 'rejected', 'discarded')),
  CONSTRAINT [CK_records_template_request_info] CHECK (ISJSON([request_info], VALUE) = 1),
  CONSTRAINT [CK_records_template_raw_dlr] CHECK (ISJSON([raw_dlr], VALUE) = 1),
  CONSTRAINT [CK_records_template_concat_parts] CHECK (ISJSON([concat_parts], VALUE) = 1),
  CONSTRAINT [CK_records_template_rate_cards] CHECK (ISJSON([rate_cards], VALUE) = 1)
);
