CREATE TABLE [tpl_hlr] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [msg_id] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  [account_id] BIGINT NULL,
  [destination] NVARCHAR(20) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [source] NVARCHAR(8) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [mcc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mnc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ported] TINYINT NOT NULL CONSTRAINT [DF_tpl_hlr_ported] DEFAULT (0),
  [charge] DECIMAL(12,6) NULL,
  [currency] CHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [looked_up_at] DATETIME2(3) NOT NULL,
  [deployment_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  CONSTRAINT [PK_tpl_hlr] PRIMARY KEY ([id])
);
CREATE INDEX [idx_acct_at] ON [tpl_hlr] ([account_id], [looked_up_at]);
CREATE INDEX [idx_at] ON [tpl_hlr] ([looked_up_at]);
CREATE INDEX [idx_dest_at] ON [tpl_hlr] ([destination], [looked_up_at]);
CREATE INDEX [idx_msg] ON [tpl_hlr] ([msg_id]);
GO

CREATE TABLE [tpl_mo] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [msg_id] CHAR(26) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [account_id] BIGINT NULL,
  [sender] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [destination] NVARCHAR(15) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [body] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [encoding] VARCHAR(6) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [segments] INT NULL,
  [route_id] BIGINT NULL,
  [vendor_id] BIGINT NULL,
  [mcc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mnc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [received_at] DATETIME2(0) NULL,
  [status] NVARCHAR(12) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mask_body] TINYINT NULL,
  [queue_owner] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [created_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_tpl_mo_created_at] DEFAULT (SYSUTCDATETIME()),
  [updated_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_tpl_mo_updated_at] DEFAULT (SYSUTCDATETIME()),
  [rate_cards] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [buy_price] DECIMAL(12,6) NULL,
  [sell_price] DECIMAL(12,6) NULL,
  [currency] CHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [rated_at] DATETIME2(0) NULL,
  [rating_attempts] INT NOT NULL CONSTRAINT [DF_tpl_mo_rating_attempts] DEFAULT (0),
  [rating_error] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [error_code] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [deployment_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [charge_batch] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  [charge] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [w_token] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  CONSTRAINT [PK_tpl_mo] PRIMARY KEY ([id]),
  CONSTRAINT [CK_tpl_mo_encoding] CHECK ([encoding] IN ('gsm7', 'ucs2', 'latin1')),
  CONSTRAINT [CK_tpl_mo_rate_cards] CHECK (ISJSON([rate_cards], VALUE) = 1)
);
CREATE INDEX [idx_acct_at] ON [tpl_mo] ([account_id], [received_at]);
CREATE INDEX [idx_received] ON [tpl_mo] ([received_at]);
CREATE INDEX [idx_sender_at] ON [tpl_mo] ([sender], [received_at]);
CREATE INDEX [idx_unrated] ON [tpl_mo] ([rated_at]);
CREATE UNIQUE INDEX [uq_msg] ON [tpl_mo] ([msg_id]);
GO

CREATE TABLE [tpl_mt] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [msg_id] CHAR(26) COLLATE Latin1_General_100_BIN2 NOT NULL,
  [trace_id] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  [request_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [account_id] BIGINT NULL,
  [company_id] BIGINT NULL,
  [sender] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [destination] NVARCHAR(15) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [body] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [body_enc] VARCHAR(13) COLLATE Latin1_General_100_CI_AS_SC NOT NULL CONSTRAINT [DF_tpl_mt_body_enc] DEFAULT (N'plain_text'),
  [campaign_hash] CHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [campaign_id] NVARCHAR(100) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [encoding] VARCHAR(6) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [segments] INT NULL,
  [sent_parts] INT NULL,
  [udh_ref] INT NOT NULL CONSTRAINT [DF_tpl_mt_udh_ref] DEFAULT (0),
  [udh_total] INT NOT NULL CONSTRAINT [DF_tpl_mt_udh_total] DEFAULT (0),
  [udh_seq] INT NOT NULL CONSTRAINT [DF_tpl_mt_udh_seq] DEFAULT (0),
  [channel] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ap1] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ap2] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [apg1] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [apg2] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [priority] INT NULL,
  [protocol] VARCHAR(9) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [ingress] VARCHAR(4) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [ip_address] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mcc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mnc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [hlr_source] NVARCHAR(8) COLLATE Latin1_General_100_CI_AS_SC NOT NULL CONSTRAINT [DF_tpl_mt_hlr_source] DEFAULT (N''),
  [hlr_ported] TINYINT NOT NULL CONSTRAINT [DF_tpl_mt_hlr_ported] DEFAULT (0),
  [vendor_id] BIGINT NULL,
  [vendor_msg_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [transport] VARCHAR(9) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [route_id] BIGINT NULL,
  [template_id] BIGINT NULL,
  [accepted_at] DATETIME2(0) NULL,
  [vendor_ack_at] DATETIME2(3) NULL,
  [status] NVARCHAR(12) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [no_receipt] TINYINT NULL,
  [failure_receipt_only] TINYINT NULL,
  [want_intermediate] TINYINT NULL,
  [bind_slot] INT NULL,
  [mask_body] TINYINT NULL,
  [told_status] NVARCHAR(12) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [told_err] NVARCHAR(16) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [told_by] NVARCHAR(24) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [told_at] DATETIME2(0) NULL,
  [queue_owner] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [rate_cards] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [buy_price] DECIMAL(12,6) NULL,
  [sell_price] DECIMAL(12,6) NULL,
  [currency] CHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [rated_at] DATETIME2(0) NULL,
  [charging_mode] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [attempt_count] INT NULL,
  [operator_bills_failure] TINYINT NULL,
  [created_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_tpl_mt_created_at] DEFAULT (SYSUTCDATETIME()),
  [updated_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_tpl_mt_updated_at] DEFAULT (SYSUTCDATETIME()),
  [client_ref] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [rating_attempts] INT NOT NULL CONSTRAINT [DF_tpl_mt_rating_attempts] DEFAULT (0),
  [rating_error] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [spam_flag] NVARCHAR(190) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [concat_parts] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [deployment_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [sent_deployment_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [sender_by] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [client_sender] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [route_level] INT NULL,
  [send_round] INT NULL,
  [billing_model] NVARCHAR(8) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [quote] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [charge_batch] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  [charge] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [w_token] CHAR(26) COLLATE Latin1_General_100_BIN2 NULL,
  [error_code] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [error_text] NVARCHAR(512) COLLATE Latin1_General_100_CI_AS_SC NULL,
  CONSTRAINT [PK_tpl_mt] PRIMARY KEY ([id]),
  CONSTRAINT [CK_tpl_mt_body_enc] CHECK ([body_enc] IN ('plain_text', 'pii_masked', 'all_encrypted')),
  CONSTRAINT [CK_tpl_mt_encoding] CHECK ([encoding] IN ('gsm7', 'ucs2', 'latin1')),
  CONSTRAINT [CK_tpl_mt_protocol] CHECK ([protocol] IN ('smpp', 'http', 'blackhole')),
  CONSTRAINT [CK_tpl_mt_ingress] CHECK ([ingress] IN ('http', 'smpp')),
  CONSTRAINT [CK_tpl_mt_transport] CHECK ([transport] IN ('smpp', 'http', 'soap', 'blackhole')),
  CONSTRAINT [CK_tpl_mt_rate_cards] CHECK (ISJSON([rate_cards], VALUE) = 1),
  CONSTRAINT [CK_tpl_mt_concat_parts] CHECK (ISJSON([concat_parts], VALUE) = 1)
);
CREATE INDEX [idx_acct_at] ON [tpl_mt] ([account_id], [accepted_at]);
CREATE INDEX [idx_campaign_hash] ON [tpl_mt] ([campaign_hash]);
CREATE INDEX [idx_campaign_id] ON [tpl_mt] ([campaign_id]);
CREATE INDEX [idx_client_ref] ON [tpl_mt] ([account_id], [client_ref]);
CREATE INDEX [idx_concat] ON [tpl_mt] ([account_id], [udh_ref], [udh_total]);
CREATE INDEX [idx_dest_at] ON [tpl_mt] ([destination], [accepted_at]);
CREATE INDEX [idx_drill] ON [tpl_mt] ([accepted_at], [vendor_id]);
CREATE INDEX [idx_request] ON [tpl_mt] ([request_id]);
CREATE INDEX [idx_unrated] ON [tpl_mt] ([rated_at]);
CREATE UNIQUE INDEX [uq_msg] ON [tpl_mt] ([msg_id]);
GO

CREATE TABLE [tpl_orphans] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [kind] VARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [vendor_id] BIGINT NULL,
  [vendor_msg_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [status] NVARCHAR(16) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [error_code] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [raw] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [source] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [destination] NVARCHAR(32) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [body] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [encoding] NVARCHAR(8) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mcc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [mnc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [reason] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [received_at] DATETIME2(0) NOT NULL,
  CONSTRAINT [PK_tpl_orphans] PRIMARY KEY ([id]),
  CONSTRAINT [CK_tpl_orphans_kind] CHECK ([kind] IN ('dlr', 'mo'))
);
CREATE INDEX [idx_destination] ON [tpl_orphans] ([destination]);
CREATE INDEX [idx_kind_at] ON [tpl_orphans] ([kind], [received_at]);
CREATE INDEX [idx_received] ON [tpl_orphans] ([received_at]);
CREATE INDEX [idx_vendor_msg] ON [tpl_orphans] ([vendor_id], [vendor_msg_id]);
GO

CREATE TABLE [tpl_rejects] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [rejected_at] DATETIME2(3) NOT NULL,
  [account_id] BIGINT NULL,
  [channel] VARCHAR(4) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [client_msg_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [sender_id] NVARCHAR(20) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [msisdn] NVARCHAR(20) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [parts] INT NOT NULL CONSTRAINT [DF_tpl_rejects_parts] DEFAULT (1),
  [reason_code] NVARCHAR(191) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [reason_text] NVARCHAR(190) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [reason_detail] NVARCHAR(128) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [reason_audit] NVARCHAR(190) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [deployment_id] NVARCHAR(64) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [body] NVARCHAR(MAX) COLLATE Latin1_General_100_CI_AS_SC NULL,
  CONSTRAINT [PK_tpl_rejects] PRIMARY KEY ([id]),
  CONSTRAINT [CK_tpl_rejects_channel] CHECK ([channel] IN ('http', 'smpp'))
);
CREATE INDEX [idx_acct] ON [tpl_rejects] ([account_id], [rejected_at]);
CREATE INDEX [idx_at] ON [tpl_rejects] ([rejected_at]);
CREATE INDEX [idx_client] ON [tpl_rejects] ([account_id], [client_msg_id]);
CREATE INDEX [idx_msisdn_at] ON [tpl_rejects] ([msisdn], [rejected_at]);
CREATE INDEX [idx_reason_at] ON [tpl_rejects] ([reason_code], [rejected_at]);
GO

CREATE TABLE [vendor_quality_minute] (
  [minute] DATETIME2(0) NOT NULL,
  [vendor_id] BIGINT NOT NULL,
  [mcc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NOT NULL CONSTRAINT [DF_vendor_quality_minute_mcc] DEFAULT (N''),
  [mnc] NVARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NOT NULL CONSTRAINT [DF_vendor_quality_minute_mnc] DEFAULT (N''),
  [delivered] BIGINT NOT NULL CONSTRAINT [DF_vendor_quality_minute_delivered] DEFAULT (0),
  [judged] BIGINT NOT NULL CONSTRAINT [DF_vendor_quality_minute_judged] DEFAULT (0),
  CONSTRAINT [PK_vendor_quality_minute] PRIMARY KEY ([minute], [vendor_id], [mcc], [mnc])
);
GO

